use fossil_base::NativeReader;
use fossil_graph_schema::{Duckdb, Primitive};

/// The [`Primitive`] a column one native reader `DESCRIBE`s means: what
/// [`Duckdb`] reads the type as, unless its row declares that primitive
/// `text`, one the reader inferred from text that the run reads as text.
/// A type outside the lattice is read as text too.
pub fn read_primitive(reader: NativeReader, t: &str) -> Primitive {
    let read = Primitive::try_from(&Duckdb::new(t)).unwrap_or(Primitive::STRING);
    let text = match reader {
        NativeReader::JsonAuto => matches!(
            read,
            Primitive::DATE | Primitive::DATE_TIME | Primitive::HOUR
        ),
        _ => false,
    };
    if text { Primitive::STRING } else { read }
}
